// Receipt fields from the Stripe PaymentIntent, HTML-escaped for the receipt template.
const pi = $json.data.object;
const settings = $('Settings').first().json;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);

// Stripe amounts are in the smallest unit; these currencies have no decimals.
const zeroDecimal = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];
const minor = pi.amount_received ?? pi.amount;
const amount = new Intl.NumberFormat('en-US', { style: 'currency', currency: pi.currency.toUpperCase() })
  .format(minor / (zeroDecimal.includes(pi.currency) ? 1 : 100));
const email = pi.receipt_email || pi.metadata?.email;

return {
  json: {
    customerEmail: email,
    customerName: esc(pi.metadata?.customer_name || email),
    description: esc(pi.description || 'Payment'),
    amount,
    paidOn: DateTime.fromSeconds(pi.created).toFormat('d LLLL yyyy'),
    paymentId: pi.id,
    receiptNumber: 'R-' + pi.id.slice(-8).toUpperCase(),
    businessName: esc(settings.businessName),
    businessAddress: esc(settings.businessAddress),
    supportEmail: esc(settings.supportEmail),
  },
};

