=<!doctype html>
<html><head><meta charset="utf-8"><style>
  body { font-family: Helvetica, Arial, sans-serif; color: #1f2933; margin: 48px; font-size: 14px; }
  .top { display: flex; justify-content: space-between; align-items: flex-start; }
  h1 { font-size: 28px; margin: 0 0 4px; letter-spacing: -0.5px; }
  .muted { color: #6b7785; }
  .paid { display: inline-block; border: 2px solid #1a7f4b; color: #1a7f4b; border-radius: 4px; padding: 4px 10px; font-weight: bold; letter-spacing: 1px; }
  table { width: 100%; border-collapse: collapse; margin-top: 32px; }
  th { text-align: left; font-size: 12px; text-transform: uppercase; color: #6b7785; border-bottom: 1px solid #d9dee3; padding: 8px 0; }
  td { padding: 12px 0; border-bottom: 1px solid #eef1f4; }
  .num { text-align: right; }
  .total td { font-size: 16px; font-weight: bold; border-bottom: none; }
  .foot { margin-top: 48px; font-size: 12px; }
</style></head><body>
  <div class="top">
    <div><h1>{{ $json.businessName }}</h1><div class="muted">{{ $json.businessAddress }}</div></div>
    <div class="num"><div class="paid">PAID</div><div class="muted" style="margin-top:8px">Receipt {{ $json.receiptNumber }}</div><div class="muted">{{ $json.paidOn }}</div></div>
  </div>
  <p style="margin-top:32px"><strong>Received from</strong><br>{{ $json.customerName }}<br><span class="muted">{{ $json.customerEmail }}</span></p>
  <table>
    <tr><th>Description</th><th class="num">Amount</th></tr>
    <tr><td>{{ $json.description }}</td><td class="num">{{ $json.amount }}</td></tr>
    <tr class="total"><td>Total paid</td><td class="num">{{ $json.amount }}</td></tr>
  </table>
  <p class="foot muted">Payment reference {{ $json.paymentId }}. Questions about this receipt? Write to {{ $json.supportEmail }}.</p>
</body></html>

